package cl.javier.starwars.config;
import cl.javier.starwars.security.JwtAuthenticationFilter; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig{
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();}
 @Bean SecurityFilterChain filterChain(HttpSecurity h,JwtAuthenticationFilter jwt)throws Exception{return h.csrf(c->c.ignoringRequestMatchers("/h2-console/**").disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).headers(x->x.frameOptions(f->f.sameOrigin())).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(401,"Token requerido o inválido")).accessDeniedHandler((req,res,ex)->res.sendError(403,"Permisos insuficientes"))).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**","/actuator/health","/h2-console/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
